    psx_icache_fetch(cpu, 0x8007A548u);
#endif
#ifdef PSX_ENABLE_BLOCK_CYCLES
    psx_cyc_step(cpu, 0x2u);
#endif
    cpu->gpr[1] = 0x800A << 16;  /* 0x800A0000 */
    PGXP_ALU(0x3C01800Au, cpu->gpr[1], 0u, 0u);  /* 0x8007A548: 0x3C01800A */
